examples:
Access the first character using the [] operator.
string name = "Alex";
char letter = name[0];
// letter = 'A'

Access the second character using the at() function.
string name = "Alex";
char letter = name.at(1);
// letter = 'l'

Change a character using its index.
string name = "Alex";
name[0] = 'F';
// name = "Flex"

Change a character using the at() function.
string name = "Alex";
name.at(3) = 'a';
// name = "Alea"

Get the number of characters in a string.
string name = "Alex";
cout << name.length();
// Outputs 4

Store the length of a string in a variable.
string message = "Hello World";
int length = message.length();
// length = 11

Get the number of characters in a string.
string name = "Alex";
cout << name.size();
// Outputs 4

Use size() as the condition of a loop.
for(int i = 0; i < name.size(); i++)
{
    cout << name[i] << endl;
}

Check if a string is empty.
string name = "";
if(name.empty())
{
    cout << "Name is empty";
}

Use the NOT operator to check if a string is not empty.
if(!name.empty())
{
    cout << name;
}

Access the first character of a string.
string name = "Alex";
cout << name.at(0);
// Outputs A

Change a character using at().
string name = "Alex";
name.at(0) = 'F';
// name = "Flex"

Get part of a string starting at index 6.
string message = "Hello World";
string word = message.substr(6);
// word = "World"

Get five characters starting at index 6.
string message = "Hello World";
string word = message.substr(6, 5);
// word = "World"

Find the starting position of a substring.
string message = "Hello World";
cout << message.find("World");
// Outputs 6

Check whether a string contains a substring.
if(message.find("World") != string::npos)
{
    cout << "Found";
}

Add one string to the end of another string.
string message = "Hello";
message.append(" World");
// message = "Hello World"

Append the contents of another string.
string firstName = "Alex";
string lastName = " Smith";
firstName.append(lastName);
// firstName = "Alex Smith"

Insert text at the beginning of a string.
string message = "World";
message.insert(0, "Hello ");
// message = "Hello World"

Insert text in the middle of a string.
string message = "HelloWorld";
message.insert(5, " ");
// message = "Hello World"

Remove characters beginning at index 5.
string message = "Hello World";
message.erase(5);
// message = "Hello"

Remove one character beginning at index 5.
string message = "Hello World";
message.erase(5, 1);
// message = "HelloWorld"

Replace part of a string with new text.
string message = "Hello World";
message.replace(6, 5, "Alex");
// message = "Hello Alex"

Replace three characters beginning at index 0.
string word = "catfish";
word.replace(0, 3, "dog");
// word = "dogfish"

Remove all characters from a string.
string name = "Alex";
name.clear();
// name is now empty

Check whether the string is empty after clearing it.
name.clear();
if(name.empty())
{
    cout << "Name is empty";
}

Compare two strings to determine if they are equal.
string name1 = "Alex";
string name2 = "Alex";
if(name1.compare(name2) == 0)
{
    cout << "The strings are equal";
}

Determine if one string comes before another string.
string name1 = "Alex";
string name2 = "Bob";
if(name1.compare(name2) < 0)
{
    cout << name1 << " comes first";
}

Find the last occurrence of a character.
