string message = "Score: " + to_string(score);
cout << message;

Convert the result of an expression to a string.
int wins = 8;
int losses = 2;
string record = to_string(wins) + "-" + to_string(losses);
cout << record;
// Outputs 8-2

Check whether a character is whitespace.
