toupper() returns an integer representing the character value.
char letter = 'a';
int value = toupper(letter);
cout << value;
// Outputs 65 for ASCII

Cast the returned value to a char to store the uppercase character.
char letter = 'a';
letter = static_cast<char>(toupper(letter));
cout << letter;
// Outputs A

Convert each character in a string to uppercase.
string word = "hello";
for(int i = 0; i < word.length(); i++)
{
    word[i] = static_cast<char>(toupper(word[i]));
}
cout << word;
// Outputs HELLO

tolower() returns an integer representing the character value.
char letter = 'A';
int value = tolower(letter);
cout << value;
// Outputs 97 for ASCII

Cast the returned value to a char to store the lowercase character.
char letter = 'A';
letter = static_cast<char>(tolower(letter));
cout << letter;
// Outputs a

Convert each character in a string to lowercase.
string word = "HELLO";
for(int i = 0; i < word.length(); i++)
{
    word[i] = static_cast<char>(tolower(word[i]));
}
cout << word;
// Outputs hello

Display the ASCII value of a character.
char letter = 'A';
cout << static_cast<int>(letter);
// Outputs 65

Convert an ASCII value to a character.
int value = 66;
cout << static_cast<char>(value);
// Outputs B

Characters can be compared using their character values.
