cout << age;

Display text and a variable in the same statement.
int age = 25;
cout << "Age: " << age;

Display multiple values and move to a new line.
string name = "Alex";
int age = 25;
cout << "Name: " << name << ", Age: " << age << endl;

Use \n to move the output to a new line.
cout << "Hello\nWorld";
// Outputs Hello and World on separate lines

Use \t to insert a horizontal tab.
