syntax:
Simple if structure:
if(condition)
{
    statements;
}

if-else structure:
if(condition)
{
    statements;
}
else
{
    statements;
}

if-else-if structure:
if(condition1)
{
    statements;
}
else if(condition2)
{
    statements;
}
else
{
    statements;
}

examples:
A simple if structure executes only when the condition is true.

if(score >= 70)
{
    cout << "Passing" << endl;
}

An if-else structure chooses between two alternatives.

if(score >= 70)
{
    cout << "Passing" << endl;
}
else
{
    cout << "Not passing" << endl;
}

An if-else-if structure evaluates several conditions in order.

if(score >= 90)
{
    cout << "Grade: A" << endl;
}
else if(score >= 80)
{
    cout << "Grade: B" << endl;
}
else if(score >= 70)
{
    cout << "Grade: C" << endl;
}
else
{
    cout << "Below C" << endl;
}

syntax:
if(condition1)
{
    if(condition2)
    {
        statements;
    }
    else
    {
        statements;
    }
}
else
{
    statements;
}

examples:
Determine whether a person is eligible to drive.

if(age >= 16)
{
    if(hasLicense)
    {
        cout << "May drive" << endl;
    }
    else
    {
        cout << "License required" << endl;
    }
}
else
{
    cout << "Too young to drive" << endl;
}

syntax:
switch(expression)
{
    case constant1:
        statements;
        break;

    case constant2:
        statements;
        break;

    default:
        statements;
}

examples:
switch(menuChoice)
{
    case 1:
        cout << "Add Student" << endl;
        break;

    case 2:
        cout << "View Students" << endl;
        break;

    case 3:
        cout << "Exit" << endl;
        break;

    default:
        cout << "Invalid menu option" << endl;
}

Equivalent if-else structure:

if(score >= 70)
{
    result = "Passing";
}
else
{
    result = "Not Passing";
}

syntax:
Open the file when the stream is declared:

ofstream outFile("output.txt");

Open the file later using open():

ofstream outFile;
outFile.open("output.txt");

Write data to the file:

outFile << data;

Close the file:

outFile.close();

Open a file in append mode:

ofstream outFile;
outFile.open("output.txt", ios::app);

or

ofstream outFile("output.txt", ios::app);Using is_open():

ofstream outFile;
outFile.open("output.txt");

if(outFile.is_open())
{
    // write to the file
}

Using the file stream as a Boolean:

ofstream outFile;
outFile.open("output.txt");

if(outFile)
{
    // write to the file
}

examples:
Opening the file when the stream is declared:

ofstream outFile("grades.txt");

outFile << "Alice" << endl;
outFile << 95 << endl;
outFile.close();

Opening the file later using open():

ofstream outFile;
outFile.open("grades.txt");

outFile << "Bob" << endl;
outFile << 88 << endl;
outFile.close();

Opening a file in append mode:

ofstream outFile("grades.txt", ios::app);

outFile << "Charlie" << endl;
outFile.close();Appending a new student record to a file:

ofstream outFile;
outFile.open("students.txt", ios::app);

outFile << studentID << ','
        << firstName << ','
        << lastName << ','
        << grade << endl;

outFile.close();Checking that an output file opened successfully:

ofstream outFile;
outFile.open("grades.txt");

if(outFile.is_open())
{
    outFile << "Alice" << endl;
    outFile.close();
}
else
{
    cout << "Unable to open file." << endl;
}

Checking that an output file opened successfully using the file stream as a Boolean expression:

ofstream outFile;
outFile.open("grades.txt");

if(outFile)
{
    outFile << "Alice" << endl;
    outFile << 95 << endl;
    outFile.close();
}
else
{
    cout << "Unable to open grades.txt." << endl;
}

