while(number != SENTINEL)
{
    total += number;

    cout << "Enter a number or -1 to stop: ";
    cin >> number;
}

cout << "Total: " << total << endl;

syntax:
flag = startingBooleanValue;

while(flag condition)
{
    statements;

    if(termination condition)
