examples:
Read and display every line in a text file:

ifstream inFile;
string line;

inFile.open("students.txt");

if(inFile.is_open())
{
    getline(inFile, line);

    while(!inFile.eof())
    {
        cout << line << endl;
        getline(inFile, line);
    }

    inFile.close();
}
else
{
