syntax:
int binarySearch(dataType arrayName[], int size, dataType key)
{
    int mid, low = 0, high = size - 1;

    while(low <= high)
    {
        mid = (low + high) / 2;

        if(arrayName[mid] == key)
        {
            return mid;
        }
        else if(arrayName[mid] < key)
        {
            low = mid + 1;
        }
        else
        {
            high = mid - 1;
        }
    }

    return -1;
}

examples:
Search a sorted array for a number:

int binarySearch(int [], int, int);

int main()
{
    int numbers[7] = {10, 20, 30, 40, 50, 60, 70};
    int foundIndex;

    foundIndex = binarySearch(numbers, 7, 60);

    if(foundIndex != -1)
    {
        cout << "Found at index " << foundIndex << endl;
    }
    else
    {
        cout << "Value not found." << endl;
    }

    return 0;
}

int binarySearch(int numbers[], int size, int key)
{
    int mid, low = 0, high = size - 1;

    while(low <= high)
    {
        mid = (low + high) / 2;

        if(numbers[mid] == key)
        {
            return mid;
        }
        else if(numbers[mid] < key)
        {
            low = mid + 1;
        }
        else
        {
            high = mid - 1;
        }
    }

    return -1;
}

