}

syntax:
for(int pass = 0; pass < size - 1; pass++)
{
    for(int index = 0; index < size - 1 - pass; index++)
    {
        if(arrayName[index] > arrayName[index + 1])
        {
            temp = arrayName[index];
            arrayName[index] = arrayName[index + 1];
            arrayName[index + 1] = temp;
        }
    }
}

examples:
Sort an integer array into ascending order:

int numbers[5] = {42, 15, 73, 8, 31};
int temp;

for(int pass = 0; pass < 4; pass++)
{
    for(int index = 0; index < 4 - pass; index++)
    {
        if(numbers[index] > numbers[index + 1])
        {
            temp = numbers[index];
            numbers[index] = numbers[index + 1];
            numbers[index + 1] = temp;
        }
    }
}

The resulting array is:
8, 15, 31, 42, 73

syntax:
int minIndex;
for(int start = 0; start < size - 1; start++)
{
    minIndex = start;

    for(int index = start + 1; index < size; index++)
    {
        if(arrayName[index] < arrayName[minIndex])
        {
            minIndex = index;
        }
    }

    temp = arrayName[start];
    arrayName[start] = arrayName[minIndex];
    arrayName[minIndex] = temp;
}

examples:
Sort an integer array into ascending order:

int numbers[5] = {42, 15, 73, 8, 31};
int temp;
int minIndex;

for(int start = 0; start < 4; start++)
{
    minIndex = start;

    for(int index = start + 1; index < 5; index++)
    {
        if(numbers[index] < numbers[minIndex])
        {
            minIndex = index;
        }
    }

    temp = numbers[start];
    numbers[start] = numbers[minIndex];
    numbers[minIndex] = temp;
}

The resulting array is:
8, 15, 31, 42, 73

syntax:
